// final class Node { var val: Int; var neighbors: [Node?] = []; init(_ v: Int) { val = v } }
func cloneGraph(_ node: Node?) -> Node? {
    var clones: [ObjectIdentifier: Node] = [:]
    func clone(_ n: Node) -> Node {
        if let c = clones[ObjectIdentifier(n)] { return c }
        let c = Node(n.val)
        clones[ObjectIdentifier(n)] = c
        c.neighbors = n.neighbors.map { $0.map(clone) }
        return c
    }
    return node.map(clone)
}
